151	// GetMemoByShare resolves a share token to its memo. No authentication required.
152	// Returns NOT_FOUND for invalid or expired tokens (no information leakage).
153	func (s *APIV1Service) GetMemoByShare(ctx context.Context, request *v1pb.GetMemoByShareRequest) (*v1pb.Memo, error) {
154		ms, err := s.getActiveMemoShare(ctx, request.ShareId)
155		if err != nil {
156			return nil, err
157		}
158	
159		memo, err := s.Store.GetMemo(ctx, &store.FindMemo{ID: &ms.MemoID})
160		if err != nil {
161			return nil, status.Errorf(codes.Internal, "failed to get memo")
162		}
163		// Treat archived or missing memos the same as an invalid token — no information leakage.
164		if memo == nil || memo.RowStatus == store.Archived {
165			return nil, status.Errorf(codes.NotFound, "not found")
166		}
167	
168		reactions, err := s.Store.ListReactions(ctx, &store.FindReaction{
169			ContentID: stringPointer(fmt.Sprintf("%s%s", MemoNamePrefix, memo.UID)),
170		})
171		if err != nil {
172			return nil, status.Errorf(codes.Internal, "failed to list reactions")
173		}
174	
175		attachments, err := s.Store.ListAttachments(ctx, &store.FindAttachment{MemoID: &memo.ID})
176		if err != nil {
177			return nil, status.Errorf(codes.Internal, "failed to list attachments")
178		}
179		relations, err := s.batchConvertMemoRelations(ctx, []*store.Memo{memo}, true)
180		if err != nil {
181			return nil, status.Errorf(codes.Internal, "failed to load memo relations")
182		}
183	
184		memoMessage, err := s.convertMemoFromStore(ctx, memo, reactions, attachments, relations[memo.ID])
185		if err != nil {
186			if stderrors.Is(err, errMemoCreatorNotFound) {
187				return nil, status.Errorf(codes.NotFound, "not found")
188			}
189			return nil, errors.Wrap(err, "failed to convert memo")
190		}
191		return memoMessage, nil
192	}
193	
194	// isMemoShareExpired returns true if the share has a defined expiry that has already passed.
195	func isMemoShareExpired(ms *store.MemoShare) bool {
196		return ms.ExpiresTs != nil && time.Now().Unix() > *ms.ExpiresTs
197	}
198	
199	func (s *APIV1Service) getActiveMemoShare(ctx context.Context, shareID string) (*store.MemoShare, error) {
200		ms, err := s.Store.GetMemoShare(ctx, &store.FindMemoShare{UID: &shareID})
201		if err != nil {
202			return nil, status.Errorf(codes.Internal, "failed to get memo share")
203		}
204		if ms == nil || isMemoShareExpired(ms) {
205			return nil, status.Errorf(codes.NotFound, "not found")
206		}
207		return ms, nil
208	}
209	
210	func stringPointer(s string) *string {
211		return &s
212	}
213	
214	// convertMemoShareFromStore converts a store MemoShare to the proto MemoShare message.
215	// name format: memos/{memoUID}/shares/{shareToken}.
216	func convertMemoShareFromStore(ms *store.MemoShare, memoUID string) *v1pb.MemoShare {
217		name := fmt.Sprintf("%s%s/%s%s", MemoNamePrefix, memoUID, MemoShareNamePrefix, ms.UID)
218		pb := &v1pb.MemoShare{
219			Name:       name,
220			CreateTime: timestamppb.New(time.Unix(ms.CreatedTs, 0)),
221		}
222		if ms.ExpiresTs != nil {
223			pb.ExpireTime = timestamppb.New(time.Unix(*ms.ExpiresTs, 0))
224		}
225		return pb
226	}
